#include <glm/glm.hpp>
#include <cmath>

struct Particle
{
    glm::vec3 position, velocity, acceleration, force;
    float density;
    float pressure;
    uint16_t hash;
};

const uint32_t TABLE_SIZE = 262144;

void parallelCalculateHashes(Particle *particles, size_t start, size_t end, float h)
{
    for (size_t i = start; i < end; ++i) {
        Particle *p = &particles[i];
        glm::ivec3 cell = {
            static_cast<int>(std::floor(p->position.x / h)),
            static_cast<int>(std::floor(p->position.y / h)),
            static_cast<int>(std::floor(p->position.z / h))
        };
        uint32_t hash = (
            (static_cast<uint32_t>(cell.x) * 73856093U)
            ^ (static_cast<uint32_t>(cell.y) * 19349663U)
            ^ (static_cast<uint32_t>(cell.z) * 83492791U)
        ) % TABLE_SIZE;
        p->hash = static_cast<uint16_t>(hash);
    }
}

